import { useContext } from 'react';

import { XYChartVisibleAxesContext } from '../context/axes/XYChartVisibleAxes.context.js';

export const useVisibleAxes = () => {
  const context = useContext(XYChartVisibleAxesContext);

  if (context === undefined) {
    throw new Error(
      'useVisibleAxes must be used within a XYChartVisibleAxesContext',
    );
  }

  return context;
};
